    @Select("SELECT * FROM builds WHERE project_id = #{projectId} ORDER BY id DESC")
    List<Build> findByProjectId(Long projectId);

    @Select("SELECT * FROM builds WHERE id = #{id}")
    Build findById(Long id);

    @Update("UPDATE builds SET status = #{status}, log_output = #{logOutput}, "
            + "artifact_path = #{artifactPath}, finished_at = #{finishedAt} WHERE id = #{id}")
    int update(Build build);

    @Delete("DELETE FROM builds WHERE id = #{id}")
    int deleteById(Long id);
}
